<script setup lang="ts">
import { onMounted, ref, reactive } from 'vue'; import { Plus, Pencil, EyeOff } from 'lucide-vue-next'; import { http, errorMessage } from '../../api/http'; import type { Page, Category } from '../../types'; import Pagination from '../../components/Pagination.vue'; import LoadingState from '../../components/LoadingState.vue'; import FormField from '../../components/FormField.vue'; import ConfirmDialog from '../../components/ConfirmDialog.vue'
const result = ref<Page<Category>>(), search = ref(''), loading = ref(true), busy = ref(false), error = ref(''), success = ref(''), editing = ref<number | null>(null), showForm = ref(false), target = ref<Category>(); const form = reactive({ name: '', slug: '', description: '', isActive: true });
async function load(page = 1) { loading.value = true; try { result.value = (await http.get<Page<Category>>('/admin/categories', { params: { search: search.value, page } })).data } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
function edit(c?: Category) { editing.value = c?.id || null; Object.assign(form, c || { name: '', slug: '', description: '', isActive: true }); showForm.value = true; error.value = '' }
async function save() { busy.value = true; error.value = ''; try { if (editing.value) await http.put(`/admin/categories/${editing.value}`, form); else await http.post('/admin/categories', form); success.value = 'Đã lưu danh mục.'; showForm.value = false; await load() } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
async function hide() { const id = target.value?.id; target.value = undefined; try { await http.delete(`/admin/categories/${id}`); success.value = 'Đã ẩn danh mục.'; await load() } catch (e) { error.value = errorMessage(e) } } onMounted(() => load())
</script>
<template><div class="section-heading"><div><span class="eyebrow">SẮP XẾP TỦ SÁCH</span><h1>Quản lý danh mục</h1></div><button class="btn" @click="edit()"><Plus :size="18" /> Thêm danh mục</button></div><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="success" class="alert success" role="status">{{ success }}</p><section v-if="showForm" class="panel"><h2>{{ editing ? 'Sửa' : 'Thêm' }} danh mục</h2><form class="form-grid" @submit.prevent="save"><FormField label="Tên danh mục" id="cat-name"><input id="cat-name" v-model="form.name" required maxlength="120"></FormField><FormField label="Slug duy nhất" id="cat-slug" hint="Chữ thường không dấu, số và dấu gạch ngang."><input id="cat-slug" v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="180"></FormField><FormField label="Mô tả" id="cat-desc"><textarea id="cat-desc" v-model="form.description" maxlength="4000"></textarea></FormField><label class="check-label"><input v-model="form.isActive" type="checkbox"> Hiển thị ở cửa hàng</label><div class="actions"><button class="btn" :disabled="busy">{{ busy ? 'Đang lưu…' : 'Lưu danh mục' }}</button><button type="button" class="btn secondary" @click="showForm = false">Đóng</button></div></form></section><section class="panel"><form class="toolbar" @submit.prevent="load()"><label class="sr-only" for="cat-search">Tìm danh mục</label><input id="cat-search" v-model="search" placeholder="Tìm tên danh mục…"><button class="btn secondary">Tìm kiếm</button></form><LoadingState v-if="loading" /><div v-else class="table-wrap"><table><thead><tr><th>Danh mục</th><th>Slug</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="c in result?.items" :key="c.id"><td><strong>{{ c.name }}</strong></td><td>{{ c.slug }}</td><td><span class="badge" :class="c.isActive ? 'paid' : 'cancelled'">{{ c.isActive ? 'Hiển thị' : 'Đã ẩn' }}</span></td><td><div class="actions"><button class="icon-btn" :aria-label="`Sửa ${c.name}`" @click="edit(c)"><Pencil :size="17" /></button><button class="icon-btn" :disabled="!c.isActive" :aria-label="`Ẩn ${c.name}`" @click="target = c"><EyeOff :size="17" /></button></div></td></tr><tr v-if="!result?.items.length"><td colspan="4">Không có danh mục phù hợp.</td></tr></tbody></table></div><Pagination v-if="result" :page="result.page" :total-pages="result.totalPages" @change="load" /></section><ConfirmDialog :open="!!target" title="Ẩn danh mục?" message="Sách thuộc danh mục sẽ không xuất hiện tại cửa hàng và không thể đặt mua. Lịch sử đơn được giữ nguyên." @close="target = undefined" @confirm="hide" /></template>